sys_ui_page.client_script:
var evPendenteDialog;
var evPendenteRecordId = '';
var evPendenteSaving = false;

function evPendenteMostrarErro(message) {
    var element = gel('ev_pending_error');

    element.textContent = message || '';
    element.style.display = message ? 'block' : 'none';
}

function evPendenteLerResposta(answer) {
    var response;

    try {
        response = JSON.parse(answer || '{}');
    } catch (error) {
        evPendenteMostrarErro('Resposta inválida do servidor.');
        return null;
    }

    if (!response || response.success !== true) {
        evPendenteMostrarErro(
            response && response.error ||
            'Não foi possível executar a ação.'
        );
        return null;
    }

    return response;
}

function evPendenteBloquear(blocked) {
    gel('ev_pending_reason').disabled = blocked;
    gel('ev_pending_confirm').disabled = blocked;
    gel('ev_pending_cancel').disabled = blocked;
}

function evPendenteCarregarOpcoes() {
    evPendenteDialog = GlideDialogWindow.get();

    if (!evPendenteDialog) {
        evPendenteMostrarErro(
            'Abra este modal pelo botão Pendente do atendimento.'
        );
        return;
    }

    evPendenteRecordId = String(
        evPendenteDialog.getPreference('sysparm_record_id') || ''
    );

    if (!evPendenteRecordId) {
        evPendenteMostrarErro('Atendimento não identificado.');
        return;
    }

    var ga = new GlideAjax(
        'x_fub_fundbrad_ev.EvPendenteAjax'
    );

    ga.addParam('sysparm_name', 'opcoes');
    ga.addParam('sysparm_record_id', evPendenteRecordId);

    ga.getXMLAnswer(function(answer) {
        var response = evPendenteLerResposta(answer);

        if (!response) {
            return;
        }

        var options = response.choices || [];
        var select = gel('ev_pending_reason');

        if (!options.length) {
            evPendenteMostrarErro(
                'Nenhum motivo de pendência disponível.'
            );
            return;
        }

        select.options.length = 0;
        select.add(new Option('-- Selecione --', ''));

        options.forEach(function(option) {
            select.add(new Option(
                option.displayValue,
                option.value
            ));
        });

        evPendenteBloquear(false);
        select.focus();
    });
}

function evPendenteConfirmar() {
    if (evPendenteSaving) {
        return false;
    }

    evPendenteMostrarErro('');

    var reason = String(
        gel('ev_pending_reason').value || ''
    ).trim();

    if (!reason) {
        evPendenteMostrarErro(
            'Selecione o motivo da pendência.'
        );
        gel('ev_pending_reason').focus();
        return false;
    }

    evPendenteSaving = true;
    evPendenteBloquear(true);

    var ga = new GlideAjax(
        'x_fub_fundbrad_ev.EvPendenteAjax'
    );

    ga.addParam('sysparm_name', 'pendenciar');
    ga.addParam('sysparm_record_id', evPendenteRecordId);
    ga.addParam('sysparm_reason', reason);

    ga.getXMLAnswer(function(answer) {
        var response = evPendenteLerResposta(answer);

        if (!response) {
            evPendenteSaving = false;
            evPendenteBloquear(false);
            return;
        }

        evPendenteDialog.destroy();
        window.top.location.reload();
    });

    return false;
}

function evPendenteCancelar() {
    if (evPendenteSaving) {
        return false;
    }

    if (evPendenteDialog) {
        evPendenteDialog.destroy();
    }

    return false;
}

addLoadEvent(evPendenteCarregarOpcoes);
